// Handle Escape key for both modal and non-modal dialogs.
// For modal dialogs this runs before the native `cancel` event and can suppress it.
// For non-modal dialogs this is the only Escape handler.
EventHandler.on(this._element, `keydown${eventKey}`, event => {
  if (event.key !== 'Escape') {
    return
  }

  event.preventDefault()

  if (!this._config.keyboard) {
    // keyboard: false — Escape must not dismiss; bounce static backdrop instead
    this._triggerBackdropTransition()
    return
  }

  // keyboard: true — Escape dismisses the dialog
  this._onCancel()
  this.hide()
})
